<section class="page container"><div class="page-title row"><div><span class="eyebrow">Halo, <?= e(auth()['name']) ?></span><h1>Dashboard Penjual</h1><p>Kelola semua iklan mobilmu dari satu tempat.</p></div><a class="btn btn-primary" href="<?= url('/mobil/tambah') ?>">+ Pasang Iklan</a></div><?php if($cars): ?><div class="table-card"><table><thead><tr><th>Mobil</th><th>Harga</th><th>Status</th><th>Diperbarui</th><th>Aksi</th></tr></thead><tbody><?php foreach($cars as $car): ?><tr><td><div class="listing"><div class="mini"><?php if($car['image']): ?><img src="<?= url($car['image']) ?>" alt=""><?php else: ?>🚘<?php endif; ?></div><div><strong><?= e($car['title']) ?></strong><small><?= e($car['year'].' · '.$car['city']) ?></small></div></div></td><td>Rp <?= number_format((int)$car['price'],0,',','.') ?></td><td><span class="status-pill <?= $car['status'] ?>"><?= $car['status']==='active'?'Aktif':'Terjual' ?></span></td><td><?= date('d M Y',strtotime($car['updated_at'])) ?></td><td><div class="actions"><a href="<?= url('/mobil/'.$car['id']) ?>">Lihat</a><a href="<?= url('/mobil/'.$car['id'].'/edit') ?>">Edit</a><form method="post" action="<?= url('/mobil/'.$car['id'].'/hapus') ?>" onsubmit="return confirm('Hapus iklan ini?')"><?= csrf_field() ?><button class="danger">Hapus</button></form></div></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><div class="empty"><div>🚙</div><h2>Belum ada iklan</h2><p>Pasang iklan pertamamu dan mulai temukan pembeli.</p><a class="btn btn-primary" href="<?= url('/mobil/tambah') ?>">Pasang Iklan</a></div><?php endif; ?></section>
